var e={material:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Profili filamento salvati - temperature, densità e il massimo flusso volumetrico che ciascuno può sostenere.`}},add:{t:0,b:{t:2,i:[{t:3}],s:`Aggiungi materiale`}},loading:{t:0,b:{t:2,i:[{t:3}],s:`Caricamento…`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Nessun materiale ancora. Aggiungine uno per iniziare a creare la tua libreria di filamenti.`}},edit:{t:0,b:{t:2,i:[{t:3}],s:`Modifica`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`Elimina`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Salva`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Annulla`}},list:{flow:{t:0,b:{t:2,i:[{t:4,k:`v`},{t:3,v:` mm³/s`}]}}},fields:{name:{t:0,b:{t:2,i:[{t:3}],s:`Nome`}},material:{t:0,b:{t:2,i:[{t:3}],s:`Tipo`}},brand:{t:0,b:{t:2,i:[{t:3}],s:`Marca`}},color:{t:0,b:{t:2,i:[{t:3}],s:`Colore`}},diameter:{t:0,b:{t:2,i:[{t:3}],s:`Diametro (mm)`}},density:{t:0,b:{t:2,i:[{t:3}],s:`Densità (g/cm³)`}},maxFlow:{t:0,b:{t:2,i:[{t:3}],s:`Flusso volumetrico massimo (mm³/s)`}},nozzleTemp:{t:0,b:{t:2,i:[{t:3}],s:`Ugello (°C)`}},bedTemp:{t:0,b:{t:2,i:[{t:3}],s:`Piano (°C)`}},notes:{t:0,b:{t:2,i:[{t:3}],s:`Note`}}},flowCheck:{exceeds:{t:0,b:{t:2,i:[{t:3,v:`Oltre il limite di `},{t:4,k:`hotend`},{t:3,v:` (`},{t:4,k:`flow`},{t:3,v:` > `},{t:4,k:`ceiling`},{t:3,v:` mm³/s)`}]}},within:{t:0,b:{t:2,i:[{t:4,k:`headroom`},{t:3,v:`% sotto il limite di `},{t:4,k:`hotend`}]}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Guida`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Guida a Material Brain`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Chiudi`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`Cos'è Material Brain?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Una libreria dei tuoi filamenti. Ogni profilo memorizza temperature, densità e il massimo flusso volumetrico che il filamento può sostenere - i valori su cui si basano taratura e slicing.`}}},flow:{title:{t:0,b:{t:2,i:[{t:3}],s:`Flusso vs limite dell'hotend`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Il flusso volumetrico massimo di ogni profilo viene confrontato con il limite dell'hotend nel catalogo, così un profilo che richiede più di quanto l'hotend possa fondere viene segnalato prima che si manifesti come sotto-estrusione.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Glossario`}}}},glossary:{volumetricFlow:{term:{t:0,b:{t:2,i:[{t:3}],s:`Flusso volumetrico`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Quanta plastica (mm³) l'hotend fonde al secondo - il vero limite di velocità per stampare veloce.`}}},density:{term:{t:0,b:{t:2,i:[{t:3}],s:`Densità`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Massa del filamento per volume (g/cm³); usata per convertire il flusso volumetrico in una portata di massa.`}}},ceiling:{term:{t:0,b:{t:2,i:[{t:3}],s:`Limite dell'hotend`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Il massimo flusso volumetrico che un hotend può sostenere, dal catalogo hardware.`}}}}},apply:{button:{t:0,b:{t:2,i:[{t:3}],s:`Preriscalda`}},applied:{t:0,b:{t:2,i:[{t:3,v:`Riscaldo `},{t:4,k:`name`},{t:3,v:` a `},{t:4,k:`nozzle`},{t:3,v:`°C ugello / `},{t:4,k:`bed`},{t:3,v:`°C piatto`}]}},busy:{t:0,b:{t:2,i:[{t:3}],s:`Stampante occupata - impossibile preriscaldare ora`}},no_temps:{t:0,b:{t:2,i:[{t:3}],s:`Nessuna temperatura impostata per questo profilo`}},error:{t:0,b:{t:2,i:[{t:3,v:`Preriscaldo non riuscito: `},{t:4,k:`error`}]}}}}};export{e as default};